```python
def most_frequent_characters(s):
    # Create a frequency dictionary
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    # If string is empty, return empty list
    if not freq:
        return []

    # Find the maximum frequency
    max_count = max(freq.values())

    # Collect all characters with max_count
    max_chars = [char for char, count in freq.items() if count == max_count]

    # Return the result as a dictionary
    return {char: count for char, count in zip(max_chars, [freq[char] for char in max_chars])]
